data.code:
// Trecho de S3Settings de uma tarefa DMS full-load-and-cdc. E o "payload" que
// decide como o bruto chega ao bucket — csv por padrao, parquet e mais
// compacto e mais rapido para o Athena consultar (fica mais barato ja no L61,
// mas o particionamento so vem no L62).
{
  "S3Settings": {
    "BucketName": "cadencia-pedidos-bruto",
    "BucketFolder": "rds/public/pedido",
    // csv e o padrao do DMS para S3; parquet reduz bytes varridos por
    // consulta do Athena, ao custo de mais CPU na tarefa de replicacao.
    "DataFormat": "csv",
    "CsvDelimiter": ",",
    "CsvRowDelimiter": "\n",
    // cddColumn: acrescenta a coluna com I (insert), U (update) ou D (delete)
    // nos arquivos de CDC. E o que preserva o DELETE fisico.
    "CdcInsertsAndUpdates": true,
    "IncludeOpForFullLoad": false,
    "TimestampColumnName": "dms_timestamp_captura"
  }
}

# dms.tf — instancia de replicacao, os dois endpoints, e a tarefa

# As duas roles abaixo tem NOME FIXO: o DMS as procura pelo nome, nao por
# parametro de configuracao. Criar com outro nome faz o servico simplesmente
# nao encontrar a role — mesmo com a permissao certa anexada.
resource "aws_iam_role" "dms_vpc" {
  name               = "dms-vpc-role"
  assume_role_policy = data.aws_iam_policy_document.confianca_dms.json
}

resource "aws_iam_role_policy_attachment" "dms_vpc" {
  role       = aws_iam_role.dms_vpc.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonDMSVPCManagementRole"
}

resource "aws_iam_role" "dms_logs" {
  name               = "dms-cloudwatch-logs-role"
  assume_role_policy = data.aws_iam_policy_document.confianca_dms.json
}

resource "aws_iam_role_policy_attachment" "dms_logs" {
  role       = aws_iam_role.dms_logs.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonDMSCloudWatchLogsRole"
}

data "aws_iam_policy_document" "confianca_dms" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["dms.amazonaws.com"]
    }
  }
}

# Instancia pequena de proposito: ela le um FLUXO (o WAL decodificado), nao
# executa consulta de agregacao — o dimensionamento certo aqui e sobre volume
# de mudanca por segundo, nao sobre tamanho da tabela de origem.
resource "aws_dms_replication_instance" "captura" {
  replication_instance_id   = "${var.projeto}-captura-cdc"
  replication_instance_class = "dms.t3.medium"
  allocated_storage          = 50
  vpc_security_group_ids     = [aws_security_group.dms.id]
  replication_subnet_group_id = aws_dms_replication_subnet_group.privada.id
  publicly_accessible         = false

  depends_on = [aws_iam_role_policy_attachment.dms_vpc, aws_iam_role_policy_attachment.dms_logs]
}

# Endpoint de ORIGEM: o PRIMARIO, nao a replica do L07. Um slot de replicacao
# logica direto numa replica padrao do RDS PostgreSQL nao e o caminho
# suportado por padrao — usar o primario evita depurar isso, e preserva a
# replica exatamente como o L07 a deixou.
resource "aws_dms_endpoint" "origem" {
  endpoint_id   = "${var.projeto}-origem-rds"
  endpoint_type = "source"
  engine_name   = "postgres"

  server_name = aws_db_instance.primario.address
  port        = 5432
  database_name = "cadencia"

  # A documentacao pede o usuario MASTER para o endpoint de origem: e ele
  # quem tem os papeis necessarios para configurar CDC. Lido do Secrets
  # Manager em execucao — nunca em texto aqui.
  username = jsondecode(data.aws_secretsmanager_secret_version.master.secret_string)["username"]
  password = jsondecode(data.aws_secretsmanager_secret_version.master.secret_string)["password"]
}

# Endpoint de DESTINO: S3, formato bruto.
resource "aws_dms_endpoint" "destino" {
  endpoint_id   = "${var.projeto}-destino-s3"
  endpoint_type = "target"
  engine_name   = "s3"

  s3_settings {
    bucket_name             = aws_s3_bucket.bruto.bucket
    bucket_folder            = "rds/public/pedido"
    service_access_role_arn  = aws_iam_role.dms_s3.arn
    data_format               = "csv"
    cdc_inserts_and_updates   = true
    # A coluna que carrega I/U/D. Sem ela, o arquivo de CDC vira so uma linha
    # nova por mudanca, sem dizer QUAL mudanca — e o DELETE some de novo,
    # pelo motivo inverso do incremental por timestamp.
    include_op_for_full_load = false
  }
}

resource "aws_dms_replication_task" "captura" {
  replication_task_id       = "${var.projeto}-captura-pedidos"
  replication_instance_arn  = aws_dms_replication_instance.captura.replication_instance_arn
  source_endpoint_arn       = aws_dms_endpoint.origem.endpoint_arn
  target_endpoint_arn       = aws_dms_endpoint.destino.endpoint_arn

  # full-load-and-cdc: copia o snapshot atual UMA vez, depois muda para
  # captura continua a partir do ponto exato em que o snapshot foi tirado.
  migration_type = "full-load-and-cdc"

  table_mappings = jsonencode({
    rules = [{
      "rule-type"   = "selection"
      "rule-id"     = "1"
      "rule-name"   = "1"
      "object-locator" = { "schema-name" = "public", "table-name" = "pedido" }
      "rule-action" = "include"
    }]
  })
}

# Menor privilegio: a tarefa so precisa escrever no PREFIXO do bucket que ela
# usa. ListBucket exige o recurso do bucket (nao do objeto); e por isso as
# duas actions abaixo apontam para ARNs diferentes.
data "aws_iam_policy_document" "dms_para_s3" {
  statement {
    effect    = "Allow"
    actions   = ["s3:PutObject", "s3:GetObject", "s3:DeleteObject"]
    resources = ["${aws_s3_bucket.bruto.arn}/rds/public/pedido/*"]
  }
  statement {
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.bruto.arn]
  }
}

// ProvarCaptura.cs — console .NET 8: confirma um DELETE fisico chegando ao S3
// via CDC, sem NENHUMA consulta ao RDS. E a prova executavel da secao seguinte.

using Amazon.Athena;
using Amazon.Athena.Model;
using Npgsql;

var athena = new AmazonAthenaClient();
const string banco = "cadencia_bruto";           // banco logico do Athena (Glue-lite, sem crawler ainda)
const string bucketSaida = "s3://cadencia-athena-resultados/";

// 1) Marca um pedido para exclusao fisica no PRIMARIO — a unica escrita deste
//    script, e o unico contato dele com o RDS transacional.
var pedidoId = Guid.NewGuid();
await using (var conexao = new NpgsqlConnection(Environment.GetEnvironmentVariable("CONN_PRIMARIO")))
{
    await conexao.OpenAsync();
    await new NpgsqlCommand(
        "insert into pedido (id, loja_id, categoria, valor, criado_em) " +
        "values (@id, 1, 'teste-cdc', 10.00, now())", conexao)
    { Parameters = { new("id", pedidoId) } }.ExecuteNonQueryAsync();

    await new NpgsqlCommand("delete from pedido where id = @id", conexao)
    { Parameters = { new("id", pedidoId) } }.ExecuteNonQueryAsync();
}

// 2) Espera a janela de atraso aceitavel (o requisito declarado: ate 24h; no
//    ambiente de laboratorio a captura costuma aparecer em minutos) e consulta
//    o S3 via Athena — NENHUMA linha abaixo abre conexao com o RDS.
var query = $"SELECT op FROM {banco}.pedido WHERE id = '{pedidoId}' ORDER BY dms_timestamp_captura DESC LIMIT 1";

var inicio = await athena.StartQueryExecutionAsync(new StartQueryExecutionRequest
{
    QueryString = query,
    QueryExecutionContext = new QueryExecutionContext { Database = banco },
    ResultConfiguration = new ResultConfiguration { OutputLocation = bucketSaida }
});

string estado;
do
{
    await Task.Delay(TimeSpan.FromSeconds(3));
    var status = await athena.GetQueryExecutionAsync(new GetQueryExecutionRequest
    { QueryExecutionId = inicio.QueryExecutionId });
    estado = status.QueryExecution.Status.State;
} while (estado is "QUEUED" or "RUNNING");

if (estado != "SUCCEEDED")
    throw new InvalidOperationException($"consulta ao Athena terminou em {estado}");

var resultado = await athena.GetQueryResultsAsync(new GetQueryResultsRequest { QueryExecutionId = inicio.QueryExecutionId });
var linha = resultado.ResultSet.Rows.Skip(1).FirstOrDefault(); // pula o cabecalho

// Esperado: "D". Se vier null, o CDC ainda nao capturou — espere mais um
// pouco ou confira CDCLatencySource/Target antes de declarar falha.
Console.WriteLine(linha is null
    ? "AINDA NAO CAPTURADO: repita em alguns minutos"
    : $"operacao capturada: {linha.Data[0].VarCharValue}");
